/work/lib/db/schema.ts.content:
import type { DatabaseSync } from "node:sqlite";

export function initializeSchema(db: DatabaseSync) {
  db.exec(`PRAGMA foreign_keys = ON; PRAGMA journal_mode = WAL;
    CREATE TABLE IF NOT EXISTS bookmarks (
      id TEXT PRIMARY KEY, url TEXT NOT NULL, normalized_url TEXT NOT NULL, title TEXT NOT NULL CHECK(length(title) BETWEEN 1 AND 300),
      description TEXT CHECK(description IS NULL OR length(description) <= 1000), notes TEXT CHECK(notes IS NULL OR length(notes) <= 10000),
      site_icon_url TEXT, preview_image_url TEXT, favorite INTEGER NOT NULL DEFAULT 0 CHECK(favorite IN (0,1)),
      reading_status TEXT NOT NULL DEFAULT 'to_read' CHECK(reading_status IN ('to_read','read')), archived_at TEXT,
      created_at TEXT NOT NULL, updated_at TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS tags (id TEXT PRIMARY KEY, name TEXT NOT NULL, normalized_name TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS bookmark_tags (bookmark_id TEXT NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE, tag_id TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(bookmark_id,tag_id));
    CREATE INDEX IF NOT EXISTS idx_bookmarks_normalized_url ON bookmarks(normalized_url);
    CREATE INDEX IF NOT EXISTS idx_bookmarks_scope ON bookmarks(archived_at, reading_status, favorite);
    CREATE INDEX IF NOT EXISTS idx_bookmarks_created ON bookmarks(created_at DESC);
    CREATE INDEX IF NOT EXISTS idx_bookmarks_updated ON bookmarks(updated_at DESC);
    CREATE INDEX IF NOT EXISTS idx_bookmark_tags_tag ON bookmark_tags(tag_id, bookmark_id);`);
}

/work/lib/bookmarks/types.ts.content:
export type ReadingStatus = "to_read" | "read";
export type Scope = "active" | "to_read" | "favorites" | "archived";
export type Sort = "created_desc" | "title_asc" | "updated_desc";

export interface Tag { id: string; name: string; bookmarkCount?: number }
export interface Bookmark {
  id: string; url: string; title: string; description: string | null; notes: string | null;
  siteIconUrl: string | null; previewImageUrl: string | null; favorite: boolean;
  readingStatus: ReadingStatus; archived: boolean; archivedAt: string | null;
  tags: Tag[]; createdAt: string; updatedAt: string;
}
export interface BookmarkInput {
  url: string; title: string; description?: string | null; notes?: string | null;
  siteIconUrl?: string | null; previewImageUrl?: string | null; favorite?: boolean;
  readingStatus?: ReadingStatus; tags?: string[]; allowDuplicate?: boolean;
}
export interface BookmarkQuery {
  scope: Scope; q?: string; tag?: string; favorite?: boolean; readingStatus?: ReadingStatus;
  sort: Sort; page: number; pageSize: number;
}
export interface MetadataPreview {
  requestedUrl: string; finalUrl: string; title: string | null; description: string | null;
  siteIconUrl: string | null; previewImageUrl: string | null; warnings: string[];
}

/work/lib/bookmarks/normalize-url.ts.content:
import { AppProblem } from "@/lib/http/problem";

export function parseWebUrl(value: string) {
  let url: URL;
  try { url = new URL(value.trim()); } catch { throw new AppProblem(422, "Invalid web address", "Enter a complete HTTP or HTTPS address.", { url: ["Enter a valid web address."] }); }
  if (!(["http:", "https:"] as string[]).includes(url.protocol) || url.username || url.password) throw new AppProblem(422, "Unsupported web address", "Only public HTTP and HTTPS addresses without embedded credentials are supported.", { url: ["Use an HTTP or HTTPS address."] });
  return url;
}

export function normalizeUrl(value: string) {
  const url = parseWebUrl(value);
  url.hash = "";
  url.protocol = url.protocol.toLowerCase();
  url.hostname = url.hostname.toLowerCase();
  if ((url.protocol === "http:" && url.port === "80") || (url.protocol === "https:" && url.port === "443")) url.port = "";
  if (!url.pathname) url.pathname = "/";
  return url.toString();
}

