 <aside className="rail"><Link href="/" className="brand" aria-label="Kept home"><span className="brand-mark">K</span><span>kept.</span></Link><nav aria-label="Bookmark views">{links.map(([href,label],i)=><Link key={href} href={href} className={path===href?"nav-link active":"nav-link"}><span aria-hidden>{["▦","◷","★","□"][i]}</span>{label}</Link>)}</nav><div className="rail-note"><span>YOUR SPACE</span><p>A quiet corner for everything worth coming back to.</p></div></aside>
