 async function mutate(item:Bookmark,kind:string){if(kind==="delete"&&!confirm(`Permanently delete “${item.title}”? This cannot be undone.`))return;let url=`/api/bookmarks/${item.id}`,method="PATCH",body:unknown=undefined;if(kind==="favorite")body={favorite:!item.favorite};if(kind==="reading")body={readingStatus:item.readingStatus==="to_read"?"read":"to_read"};if(kind==="archive"||kind==="restore"){url+=`/${kind}`;method="POST"}if(kind==="delete")method="DELETE";const r=await fetch(url,{method,headers:body?{"content-type":"application/json"}:undefined,body:body?JSON.stringify(body):undefined});if(r.ok){setNotice(kind==="delete"?"Bookmark permanently deleted.":kind==="archive"?"Bookmark moved to the archive.":kind==="restore"?"Bookmark restored to your library.":"Bookmark updated.");load()}else setNotice("That change couldn't be completed.")}
 const [title,subtitle]=copy[scope];return <AppShell ready={ready}><main><header className="page-header"><div><span className="eyebrow">{scope==="active"?"THE GOOD STUFF":scope.replace("_"," ").toUpperCase()}</span><h1>{title}<span className="count">{total}</span></h1><p>{subtitle}</p></div><button className="primary add" onClick={()=>setForm("new")}><span>＋</span> Add bookmark</button></header><BookmarkFilters q={q} setQ={v=>{setQ(v);setPage(1)}} tag={tag} setTag={v=>{setTag(v);setPage(1)}} reading={reading} setReading={v=>{setReading(v);setPage(1)}} sort={sort} setSort={v=>{setSort(v);setPage(1)}} tags={tags}/>{notice&&<div className="notice" role="status">{notice}<button onClick={()=>setNotice("")}>×</button></div>}<div className={busy?"grid loading":"grid"}>{items.map(item=><BookmarkCard key={item.id} item={item} onEdit={()=>setForm(item)} onMutate={kind=>mutate(item,kind)}/>)}</div>{ready&&!items.length&&<EmptyState archive={scope==="archived"} filtered={Boolean(q||tag||reading)}/>} {total>24&&<div className="pagination"><button disabled={page===1} onClick={()=>setPage(v=>v-1)}>← Previous</button><span>Page {page} of {Math.ceil(total/24)}</span><button disabled={page*24>=total} onClick={()=>setPage(v=>v+1)}>Next →</button></div>}</main>{form&&<BookmarkForm bookmark={form==="new"?null:form} onClose={()=>setForm(null)} onSaved={()=>{setForm(null);setNotice("Bookmark saved to your shelf.");load()}}/>}</AppShell>}

